function [valid, sp, done] = sgact_modes_dispatch(mode, phase, p, t, fb)
%SGACT_MODES_DISPATCH generated by tools/gen_sgact_spec.py from sgact_panel.toml (crc 0x82901059): DO NOT EDIT.
%   the mode with id mode: phase 1 run, 2 stop; p: its parameters (1 x MAX_PARAMS); t: s since the phase started
%   only the modes w/ impl = matlab: the ones w/ impl = simulink are subsystems of USER CONTROL (sgact_sync_modes)
%   valid: there is a MIT for the motor_cubemars (sp(1:5)), sp = [kp kd pos vel torque mmtarget], done: the stop is over
    valid = false;
    sp = zeros(1, 6);
    done = true;
    switch mode
        case 0
            [valid, sp, done] = sgact_mode_motor_cubemars_position(phase, p, t, fb);
        case 1
            [valid, sp, done] = sgact_mode_motor_cubemars_velocity_step(phase, p, t, fb);
        case 2
            [valid, sp, done] = sgact_mode_motor_cubemars_idle(phase, p, t, fb);
        case 10
            [valid, sp, done] = sgact_mode_motor_macro_velocity(phase, p, t, fb);
        case 11
            [valid, sp, done] = sgact_mode_motor_macro_current(phase, p, t, fb);
        case 12
            [valid, sp, done] = sgact_mode_motor_macro_voltage(phase, p, t, fb);
        case 30
            [valid, sp, done] = sgact_mode_idle(phase, p, t, fb);
    end
end
